mapper.update:
UPDATE product
category_id = #{categoryId}, name = #{name}, summary = #{summary}, detail_content = #{detailContent}, status = #{status}, shipping_price = #{shippingPrice}, updated_by = #{modifiedBy}
WHERE product_id = #{productId}

UPDATE product
SET display_price = (
    SELECT MIN(price) FROM product_variant
    WHERE product_id = #{productId} AND status = 'ON_SALE' AND is_deleted = false
)
WHERE product_id = #{productId}

UPDATE product_variant
option_label = #{optionLabel}, price = #{price}, status = #{status}, sort_order = #{sortOrder},
WHERE product_variant_id = #{productVariantId}

mapper.select:
SELECT COUNT(*)
FROM inquiry i


        AND i.product_id = #{productId}


        AND i.is_answered = #{isAnswered}


        AND i.is_secret = 'N'

    AND i.upper_inquiry_id IS NULL
